function trimStr(v) {
  if (v === null || v === undefined) return '';
  return String(v).trim();
}

const name = trimStr(body.name);
const email = trimStr(body.email).toLowerCase();
const message = trimStr(body.message);
const phone = trimStr(body.phone);
const company = trimStr(body.company);
const job_title = trimStr(body.job_title ?? body.jobTitle);
const budget = trimStr(body.budget);
const source = trimStr(body.source) || 'website';

const validation_errors = [];
if (!name) validation_errors.push('name is required');
if (!email) {
  validation_errors.push('email is required');
} else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  validation_errors.push('email format is invalid');
}
if (!message) validation_errors.push('message is required');

const valid = validation_errors.length === 0;
const request_id = 'req_' + Date.now().toString(36) + '_' + Math.random().toString(36).substring(2, 10);
const received_at = new Date().toISOString();

return {
  json: {
    request_id,
    source,
    name,
    email,
    phone,
    company,
    job_title,
    budget,
    message,
    received_at,
    valid,
    validation_errors
  }
};

function djb2Hash(str) {
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) + hash + str.charCodeAt(i)) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
}

const normalizedEmail = String($json.email || '').trim().toLowerCase();
const normalizedMessage = String($json.message || '').trim().toLowerCase().replace(/\s+/g, ' ');
const basis = normalizedEmail + '|' + normalizedMessage;
const idempotency_key = djb2Hash(basis) + '_' + basis.length;

return {
  json: {
    ...$json,
    idempotency_key: idempotency_key
  }
};

const current = $('Compute Idempotency Key').item.json;

