const original = $('Mark Not Duplicate').item.json;
const classification = $('Validate Classification Output').item.json;

function extractJson(raw) {
  if (raw === null || raw === undefined) return null;
  if (typeof raw === 'object' && !Array.isArray(raw)) return raw;
  if (typeof raw !== 'string') return null;
  let text = raw.trim();
  const fenceMatch = text.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fenceMatch) {
    text = fenceMatch[1].trim();
  }
  if (!(text.startsWith('{') && text.endsWith('}'))) {
    const braceMatch = text.match(/\{[\s\S]*\}/);
    if (braceMatch) {
      text = braceMatch[0];
    }
  }
  try {
    const result = JSON.parse(text);
    if (result && typeof result === 'object' && !Array.isArray(result)) return result;
    return null;
  } catch (e) {
    return null;
  }
}

function normalizeBoolean(value) {
  if (value === true) return true;
  if (value === false) return false;
  if (typeof value === 'string') {
    const v = value.trim().toLowerCase();
    if (v === 'true' || v === 'yes' || v === '1') return true;
    if (v === 'false' || v === 'no' || v === '0') return false;
  }
  return undefined;
}

function parseBudgetValue(budgetStr) {
  if (typeof budgetStr !== 'string' || !budgetStr.trim()) return 0;
  const cleaned = budgetStr.replace(/[^0-9.]/g, '');
  const num = parseFloat(cleaned);
  return Number.isNaN(num) ? 0 : num;
}

const decisionMakerTitles = ['owner', 'founder', 'ceo', 'coo', 'cto', 'cmo', 'vp', 'director', 'head', 'general manager', 'operations manager', 'marketing manager'];
function isDecisionMaker(jobTitle) {
  if (typeof jobTitle !== 'string' || !jobTitle.trim()) return false;
  const t = jobTitle.toLowerCase();
  return decisionMakerTitles.some((title) => t.includes(title));
}

const aiSignalKeys = ['clear_business_need', 'specific_automation_need', 'urgency_or_timeline', 'pricing_demo_or_call_request', 'strong_purchase_intent'];

const parsed = extractJson($json.output);
let malformed = parsed === null;

const qualification_signals = {};
if (!malformed) {
  for (const key of aiSignalKeys) {
    if (Object.prototype.hasOwnProperty.call(parsed, key)) {
      const norm = normalizeBoolean(parsed[key]);
      if (norm === undefined) {
        malformed = true;
        break;
      }
      qualification_signals[key] = norm;
    } else {
      qualification_signals[key] = false;
    }
  }
}

const budget_value = parseBudgetValue(original.budget);
const budget_provided = budget_value > 0;
const high_budget = budget_value >= 10000;
const decision_maker = isDecisionMaker(original.job_title);

if (!malformed) {
  qualification_signals.decision_maker = decision_maker;
  qualification_signals.budget_provided = budget_provided;
  qualification_signals.high_budget = high_budget;
}

let lead_score = null;
let lead_category = 'review';

if (!malformed) {
  const weights = { clear_business_need: 2, specific_automation_need: 2, decision_maker: 1, budget_provided: 1, high_budget: 1, urgency_or_timeline: 1, pricing_demo_or_call_request: 1, strong_purchase_intent: 1 };
  lead_score = 0;
  for (const key of Object.keys(weights)) {
    if (qualification_signals[key]) lead_score += weights[key];
  }
  lead_score = Math.max(0, Math.min(10, lead_score));
  lead_category = lead_score >= 8 ? 'high' : (lead_score >= 5 ? 'medium' : 'low');
}

let lead_intent = 'unknown';
if (!malformed && typeof parsed.lead_intent === 'string' && parsed.lead_intent.trim()) {
  lead_intent = parsed.lead_intent.trim().toLowerCase();
}

const summary = (!malformed && typeof parsed.summary === 'string' && parsed.summary.trim())
  ? parsed.summary.trim()
  : (malformed ? 'AI signal extraction was missing or invalid; routed to manual review.' : 'No summary provided.');

const recommended_action = (!malformed && typeof parsed.recommended_action === 'string' && parsed.recommended_action.trim())
  ? parsed.recommended_action.trim()
  : (malformed ? 'Manual review required.' : 'Manual review recommended.');

let reason;
if (malformed) {
  reason = 'AI output could not be parsed as valid JSON, or contained unrecognized signal values; routed to manual review.';
} else {
  const trueSignals = Object.keys(qualification_signals).filter((k) => qualification_signals[k]);
  reason = 'Score ' + lead_score + '/10 from signals: ' + (trueSignals.length ? trueSignals.join(', ') : 'none detected') + '; budget_value=' + budget_value;
}

return {
  json: {
    request_id: original.request_id,
    email: classification.email,
    intent: classification.intent,
    qualification_signals: qualification_signals,
    budget_value: budget_value,
    lead_score: lead_score,
    lead_category: lead_category,
    lead_intent: lead_intent,
    summary: summary,
    reason: reason,
    recommended_action: recommended_action,
    malformed_ai_output: malformed,
    qualification_status: malformed ? 'malformed' : 'ok',
    requires_human: malformed
  }
};

