      score: score,
      title: typeof metadata.title === 'string' ? metadata.title : 'unknown',
      source: typeof metadata.source === 'string' ? metadata.source : 'unknown',
      content: pageContent
    };
  }).filter((d) => d.content && d.content.trim());
}

const top_score = docs.length ? Math.max(...docs.map((d) => d.score)) : 0;
const retrieval_ok = !looksLikeError && docs.length > 0 && top_score > 0;

const context_block = docs
  .slice(0, 4)
  .map((d) => '[' + d.source + '] ' + d.title + ': ' + d.content)
  .join('\n')
  .slice(0, 2000);

const evidence_sources = docs.map((d) => d.source);

return [{
  json: {
    retrieval_ok: retrieval_ok,
    top_score: top_score,
    context_block: context_block,
    evidence_sources: evidence_sources
