if (typeof httpCode === 'string') { const n = parseInt(httpCode, 10); httpCode = Number.isNaN(n) ? null : n; }

const rawMessage = typeof rawError.message === 'string' ? rawError.message : 'CRM/API call failed.';
const isNetworkTransient = /ETIMEDOUT|ECONNRESET|ECONNREFUSED|ENOTFOUND|EAI_AGAIN|timed?\s*out|timeout|network error|socket hang up/i.test(rawMessage);

const RETRYABLE_CODES = [429, 500, 502, 503, 504];
const NONRETRYABLE_CODES = [400, 401, 403];

let retryable = false;
let error_code;
if (httpCode && RETRYABLE_CODES.includes(httpCode)) { retryable = true; error_code = 'HTTP_' + httpCode; }
else if (httpCode && NONRETRYABLE_CODES.includes(httpCode)) { retryable = false; error_code = 'HTTP_' + httpCode; }
else if (isNetworkTransient) { retryable = true; error_code = 'NETWORK_TIMEOUT'; }
else { retryable = false; error_code = httpCode ? ('HTTP_' + httpCode) : 'CRM_CALL_FAILED'; }

